pub enum Msg {
    Ping,
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
    }
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    fn encode_roundtrip(msg: &Msg) -> Result<Msg, String> {
        decode(&encode(msg))
    }

    #[test]
    fn ping_encode_roundtrip() {
        assert!(matches!(encode_roundtrip(&Msg::Ping), Ok(Msg::Ping)));
    }
}

