pub fn decode(bytes: &str) -> Result<Msg, String> {
    if let Some(name) = bytes.strip_prefix("{\"v\":2,\"hello\":\"") {
        if let Some(name) = name.strip_suffix("\"}") {
            return Ok(Msg::Hello(unescape_json(name)?));
        }
    }

    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    Err("unknown".into())
}

fn unescape_json(value: &str) -> Result<String, String> {
    let mut result = String::new();
    let mut escaped = false;
    for character in value.chars() {
        if escaped {
            match character {
                '\\' => result.push('\\'),
                '"' => result.push('"'),
                'n' => result.push('\n'),
                'r' => result.push('\r'),
                't' => result.push('\t'),
                _ => return Err("unknown".into()),
            }
            escaped = false;
        } else if character == '\\' {
            escaped = true;
        } else {
            result.push(character);
        }
    }
    if escaped {
        return Err("unknown".into());
    }
    Ok(result)
}

fn escape_json(value: &str) -> String {
    value
        .replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
        .replace('\t', "\\t")
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(name) => format!("{{\"v\":2,\"hello\":\"{}\"}}", escape_json(name)),
    }
}

